file_nodes.content:
variable "name" {}
variable "description" {}
variable "vpc_id" {}
variable "ingress" {
  type = list(object({
    from_port       = number
    to_port         = number
    protocol        = string
    cidr_blocks     = optional(list(string), [])
    security_groups = optional(list(string), [])
  }))
}
variable "tags" {
  type = map(string)
}

resource "aws_security_group" "this" {
  name        = var.name
  description = var.description
  vpc_id      = var.vpc_id

  dynamic "ingress" {
    for_each = var.ingress
    content {
      from_port       = ingress.value.from_port
      to_port         = ingress.value.to_port
      protocol        = ingress.value.protocol
      cidr_blocks     = lookup(ingress.value, "cidr_blocks", [])
      security_groups = lookup(ingress.value, "security_groups", [])
    }
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  lifecycle {
    create_before_destroy = true
  }

  tags = var.tags
}

output "security_group_id" {
  value = aws_security_group.this.id
}

variable "name" {
  type = string
}

variable "vpc_id" {
  type = string
}

variable "subnets" {
  type = list(string)
}

variable "cert_arn" {
  type = string
}

variable "environment" {
  type = string
}

variable "target_groups" {
  description = "Map of target groups: { name = { port, protocol, optional health_check_path } }"
  type = map(object({
    port              = number
    protocol          = string
    health_check_path = optional(string)
  }))
}


variable "internal" {
  description = "Whether the ALB is internal or internet-facing"
  type        = bool
  default     = false
}

variable "security_groups" {
  description = "List of SGs for ALB"
  type        = list(string)
  default     = []
}

variable "allow_http" {
  description = "Enable optional HTTP listener"
  type        = bool
  default     = false
}

output "db_instance_id" {
  value = aws_db_instance.this.id
}

output "db_instance_endpoint" {
  value = aws_db_instance.this.endpoint
}

output "db_subnet_group" {
  value = aws_db_subnet_group.this.name
}

variable "bucket_names" {
  description = "List of S3 bucket names to create or import"
  type        = list(string)
}

resource "aws_s3_bucket" "this" {
  for_each = { for bucket_name in var.bucket_names : bucket_name => bucket_name }
  bucket   = each.value
}

output "buckets" {
  value = aws_s3_bucket.this
}

{
  "pythonVersion": "3.11",
  "extraPaths": ["."]
}

variable "function_name" {
  description = "Name of the Lambda function"
  type        = string
}

variable "runtime" {
  description = "Lambda runtime"
  type        = string
  default     = "python3.11"
}

variable "timeout" {
  description = "Lambda timeout in seconds"
  type        = number
  default     = 30
}

variable "memory_size" {
  description = "Lambda memory size in MB"
  type        = number
  default     = 256
}

variable "log_retention_days" {
  description = "CloudWatch log retention in days"
  type        = number
  default     = 7
}

variable "target_queue_url" {
  description = "SQS queue URL to send messages to"
  type        = string
}

variable "target_queue_arn" {
  description = "SQS queue ARN to send messages to"
  type        = string
}

variable "environment_variables" {
  description = "Additional environment variables for Lambda"
  type        = map(string)
  default     = {}
}

variable "enable_s3_trigger" {
  description = "Enable S3 trigger for Lambda"
  type        = bool
  default     = true
}

variable "create_s3_notification" {
  description = "Create S3 bucket notification configuration"
  type        = bool
  default     = true
}

variable "s3_bucket_id" {
  description = "S3 bucket ID for notifications"
  type        = string
  default     = ""
}

variable "s3_bucket_arn" {
  description = "S3 bucket ARN for Lambda permissions"
  type        = string
  default     = ""
}

variable "s3_events" {
  description = "S3 events to trigger Lambda"
  type        = list(string)
  default     = ["s3:ObjectCreated:*"]
}

variable "s3_filter_prefix" {
  description = "S3 object key prefix filter"
  type        = string
  default     = ""
}

variable "s3_filter_suffix" {
  description = "S3 object key suffix filter"
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags to apply to resources"
  type        = map(string)
  default     = {}
}

########################################
# LAMBDA MODULE
########################################

# IAM Role for Lambda
resource "aws_iam_role" "lambda" {
  name = "${var.function_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(
    var.tags,
    {
      Name = "${var.function_name}-role"
    }
  )
}

# IAM Policy for Lambda to write CloudWatch Logs
resource "aws_iam_role_policy" "lambda_logging" {
  name = "lambda-logging"
  role = aws_iam_role.lambda.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

# IAM Policy for Lambda to send messages to SQS
resource "aws_iam_role_policy" "lambda_sqs" {
  name = "lambda-sqs-access"
  role = aws_iam_role.lambda.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "sqs:SendMessage",
          "sqs:GetQueueUrl",
          "sqs:GetQueueAttributes"
        ]
        Resource = var.target_queue_arn
      }
    ]
  })
}

# CloudWatch Log Group for Lambda
resource "aws_cloudwatch_log_group" "lambda" {
  name              = "/aws/lambda/${var.function_name}"
  retention_in_days = var.log_retention_days

  tags = var.tags
}

# Create a ZIP file of the Lambda code
data "archive_file" "lambda_zip" {
  type        = "zip"
  output_path = "${path.module}/lambda_package.zip"

  source {
    content  = file("${path.module}/src/s3_to_celery.py")
    filename = "lambda_function.py"
  }
}

# Lambda Function
resource "aws_lambda_function" "main" {
  filename         = data.archive_file.lambda_zip.output_path
  function_name    = var.function_name
  role            = aws_iam_role.lambda.arn
  handler         = "lambda_function.lambda_handler"
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256
  runtime         = var.runtime
  timeout         = var.timeout
  memory_size     = var.memory_size

  environment {
    variables = merge(
      {
        CELERY_QUEUE_URL = var.target_queue_url
      },
      var.environment_variables
    )
  }

  depends_on = [
    aws_cloudwatch_log_group.lambda,
    aws_iam_role_policy.lambda_logging,
    aws_iam_role_policy.lambda_sqs
  ]

  tags = merge(
    var.tags,
    {
      Name = var.function_name
    }
  )
}

# Lambda Permission for S3 to invoke
resource "aws_lambda_permission" "allow_s3" {
  count = var.enable_s3_trigger ? 1 : 0

  statement_id  = "AllowExecutionFromS3"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.main.function_name
  principal     = "s3.amazonaws.com"
  source_arn    = var.s3_bucket_arn
}

# S3 Bucket Notification (optional, controlled by variable)
resource "aws_s3_bucket_notification" "lambda_trigger" {
  count  = var.enable_s3_trigger && var.create_s3_notification ? 1 : 0
  bucket = var.s3_bucket_id

  lambda_function {
    lambda_function_arn = aws_lambda_function.main.arn
    events              = var.s3_events
    filter_prefix       = var.s3_filter_prefix
    filter_suffix       = var.s3_filter_suffix
  }

  depends_on = [aws_lambda_permission.allow_s3]
}

output "function_name" {
  description = "Lambda function name"
  value       = aws_lambda_function.main.function_name
}

output "function_arn" {
  description = "Lambda function ARN"
  value       = aws_lambda_function.main.arn
}

output "function_invoke_arn" {
  description = "Lambda function invoke ARN"
  value       = aws_lambda_function.main.invoke_arn
}

output "function_qualified_arn" {
  description = "Lambda function qualified ARN"
  value       = aws_lambda_function.main.qualified_arn
}

output "role_arn" {
  description = "Lambda execution role ARN"
  value       = aws_iam_role.lambda.arn
}

output "role_name" {
  description = "Lambda execution role name"
  value       = aws_iam_role.lambda.name
}

output "log_group_name" {
  description = "CloudWatch log group name"
  value       = aws_cloudwatch_log_group.lambda.name
}

output "log_group_arn" {
  description = "CloudWatch log group ARN"
  value       = aws_cloudwatch_log_group.lambda.arn
}

variable "env" {
  description = "Environment name (staging/prod)"
  type        = string
}

variable "additional_policy_arns" {
  type    = list(string)
  default = []
}

########################################
# EC2 IAM Role
########################################

# Create the IAM role for EC2
resource "aws_iam_role" "ec2_role" {
  name               = "stitchsense-${var.env}-ec2-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  description        = "EC2 role for ${var.env} environment"
}

# Assume role policy allowing EC2 to assume this role
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

# Attach managed policies (optional: e.g., SSM, CloudWatch)
resource "aws_iam_role_policy_attachment" "ssm" {
  for_each = toset(
    concat(
      [
        "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore",
        "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
      ],
      var.additional_policy_arns
    )
  )

  role       = aws_iam_role.ec2_role.name
  policy_arn = each.value
}

# Create an instance profile for the EC2 module
resource "aws_iam_instance_profile" "ec2_profile" {
  name = "stitchsense-${var.env}-ec2-profile"
  role = aws_iam_role.ec2_role.name
}

# ECR Access for EC2
resource "aws_iam_role_policy" "ec2_ecr_access" {
  name = "stitchsense-${var.env}-ec2-ecr-access"
  role = aws_iam_role.ec2_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage"
        ]
        Resource = "*"
      }
    ]
  })
}

########################################
# AppSync VPC Role (existing)
########################################

resource "aws_iam_role" "appsync_vpc" {
  name = "stitchsense-${var.env}-appsync-vpc-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Principal = {
        Service = "appsync.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })

  tags = {
    Name        = "stitchsense-${var.env}-appsync-vpc-role"
    Environment = var.env
  }
}

resource "aws_iam_role_policy" "appsync_vpc" {
  name = "stitchsense-${var.env}-appsync-vpc-policy"
  role = aws_iam_role.appsync_vpc.id

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Action = [
          "ec2:DescribeNetworkInterfaces",
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeVpcs",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups"
        ]
        Resource = "*"
      }
    ]
  })
}

########################################
# AppSync Service Role for HTTP DataSource & CloudWatch Logs
########################################

resource "aws_iam_role" "appsync_service_role" {
  name = "stitchsense-${var.env}-appsync-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "appsync.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })

  tags = {
    Name        = "stitchsense-${var.env}-appsync-service-role"
    Environment = var.env
  }
}

# Inline policy for CloudWatch Logs
resource "aws_iam_role_policy" "appsync_cloudwatch_logs" {
  name = "appsync-cloudwatch-logs-policy"
  role = aws_iam_role.appsync_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

# Attach AWS managed policy for AppSync CloudWatch Logs
resource "aws_iam_role_policy_attachment" "appsync_cloudwatch_logs_managed" {
  role       = aws_iam_role.appsync_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSAppSyncPushToCloudWatchLogs"
}

output "role_name" {
  description = "Name of the IAM role"
  value       = aws_iam_role.ec2_role.name
}

output "profile" {
  description = "IAM instance profile name to attach to EC2"
  value       = aws_iam_instance_profile.ec2_profile.name
}
output "appsync_service_role_arn" {
  value = aws_iam_role.appsync_vpc.arn
}

variable "certificates" {
  description = "Map of ACM certificates to manage"
  type = map(object({
    domain_name               = string
    subject_alternative_names = optional(list(string), [])
    validation_method         = optional(string, "DNS")
  }))
}

variable "route53_zone_id" {
  description = "Hosted Zone ID for DNS validation (optional)"
  type        = string
  default     = ""
}

resource "aws_acm_certificate" "cert" {
  for_each = var.certificates

  domain_name               = each.value.domain_name
  validation_method         = lookup(each.value, "validation_method", "DNS")
  subject_alternative_names = lookup(each.value, "subject_alternative_names", [])

  tags = {
    Name        = "stitchsense-cert-${each.key}"
    Environment = "production"
    Project     = "StitchSense"
    Owner       = "DevOps"
  }

  lifecycle {
    create_before_destroy = true
  }
}



# Flatten DVOs to be able to create Route53 records
locals {
  dvo_records = var.route53_zone_id == "" ? {} : {
    for pair in flatten([
      for cert_key, cert in aws_acm_certificate.cert : [
        for dvo in cert.domain_validation_options : {
          key   = "${cert_key}:${dvo.domain_name}"
          zone  = var.route53_zone_id
          name  = dvo.resource_record_name
          type  = dvo.resource_record_type
          value = dvo.resource_record_value
        }
      ]
    ]) : pair.key => pair
  }
}

resource "aws_route53_record" "validation_records" {
  for_each = local.dvo_records

  zone_id = each.value.zone
  name    = each.value.name
  type    = each.value.type
  ttl     = 60
  records = [each.value.value]

  allow_overwrite = true


}



resource "aws_acm_certificate_validation" "validation" {
  for_each = aws_acm_certificate.cert

  certificate_arn = each.value.arn
  validation_record_fqdns = [
    for dvo in each.value.domain_validation_options :
    aws_route53_record.validation_records["${each.key}:${dvo.domain_name}"].fqdn
  ]
}

output "certificate_arns" {
  description = "ARNs of all managed ACM certificates"
  value       = { for k, v in aws_acm_certificate.cert : k => v.arn }
}

variable "table_name" {
  type = string
}

variable "billing_mode" {
  type    = string
  default = "PAY_PER_REQUEST"
}

variable "hash_key" {
  type    = string
  default = "LockID"
}

variable "attributes" {
  type = list(object({
    name = string
    type = string
  }))
}

resource "aws_dynamodb_table" "this" {
  name         = var.table_name
  billing_mode = var.billing_mode
  hash_key     = var.hash_key

  dynamic "attribute" {
    for_each = var.attributes
    content {
      name = attribute.value.name
      type = attribute.value.type
    }
  }
}

output "table_name" {
  value = aws_dynamodb_table.this.name
}

output "table_arn" {
  value = aws_dynamodb_table.this.arn
}

variable "repositories" {
  description = "List of ECR repository names to create"
  type        = list(string)
}

variable "lifecycle_policies" {
  description = "Map of repository name to lifecycle policy JSON string"
  type        = map(string)
  default     = {}
}

variable "repository_policies" {
  description = "Map of repository name to repository policy JSON string"
  type        = map(string)
  default     = {}
}

variable "region" {
  type        = string
  description = "AWS region for the ECR registry"
}

# Create ECR repositories
resource "aws_ecr_repository" "this" {
  for_each = toset(var.repositories)
  name     = each.value

  image_scanning_configuration {
    scan_on_push = true
  }
}

# Apply lifecycle policies
resource "aws_ecr_lifecycle_policy" "this" {
  for_each   = { for k, v in var.lifecycle_policies : k => v }
  repository = aws_ecr_repository.this[each.key].name
  policy     = each.value
}

# Apply repository policies
resource "aws_ecr_repository_policy" "this" {
  for_each   = { for k, v in var.repository_policies : k => v }
  repository = aws_ecr_repository.this[each.key].name
  policy     = each.value
}

output "repository_arns" {
  value = { for k, v in aws_ecr_repository.this : k => v.arn }
}

output "repository_urls" {
  value = { for k, v in aws_ecr_repository.this : k => v.repository_url }
}

data "aws_caller_identity" "current" {}

output "registry" {
  value       = "${data.aws_caller_identity.current.account_id}.dkr.ecr.${var.region}.amazonaws.com"
  description = "ECR registry URL"
}

