########################################
# SES MODULE - modules/ses/variables.tf
########################################

variable "domain" {
  description = "Domain name to verify for SES"
  type        = string
}

variable "configuration_set_name" {
  description = "Name of the SES configuration set"
  type        = string
}

variable "environment" {
  description = "Environment name (staging, production, etc.)"
  type        = string
  default     = "staging"
}

# Route53 Configuration
variable "create_route53_records" {
  description = "Whether to create Route53 records for domain verification and DKIM"
  type        = bool
  default     = true
}

variable "route53_zone_id" {
  description = "Route53 hosted zone ID for DNS records"
  type        = string
  default     = ""
}

# Configuration Set Options
variable "tls_policy" {
  description = "TLS policy for emails (Optional or Require)"
  type        = string
  default     = "Require"

  validation {
    condition     = contains(["Optional", "Require"], var.tls_policy)
    error_message = "TLS policy must be either 'Optional' or 'Require'."
  }
}

variable "enable_reputation_metrics" {
  description = "Enable reputation metrics for the configuration set"
  type        = bool
  default     = true
}

variable "sending_enabled" {
  description = "Enable sending for the configuration set"
  type        = bool
  default     = true
}

# CloudWatch Events
variable "enable_cloudwatch_events" {
  description = "Enable CloudWatch event destination"
  type        = bool
  default     = true
}

variable "cloudwatch_event_types" {
  description = "Types of events to send to CloudWatch"
  type        = list(string)
  default     = ["send", "bounce", "complaint", "delivery", "reject"]
}

# SNS Events
variable "enable_sns_events" {
  description = "Enable SNS event destination for bounces and complaints"
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "SNS topic ARN for bounce/complaint notifications"
  type        = string
  default     = ""
}

variable "sns_event_types" {
  description = "Types of events to send to SNS"
  type        = list(string)
  default     = ["bounce", "complaint"]
}

# Email Templates
variable "email_templates" {
  description = "Map of email templates to create"
  type = map(object({
    subject = string
    html    = string
    text    = string
  }))
  default = {}
}

# Verified Email Addresses
variable "verified_emails" {
  description = "List of email addresses to verify (for sandbox testing)"
  type        = list(string)
  default     = []
}

# Email Receiving (optional)
variable "enable_email_receiving" {
  description = "Enable SES to receive emails"
  type        = bool
  default     = false
}

variable "receipt_rule_set_name" {
  description = "Name of the receipt rule set"
  type        = string
  default     = "default-rule-set"
}

# Tags
variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

########################################
# SES MODULE - modules/ses/main.tf
########################################

# SES Email Identity - Domain verification
resource "aws_ses_domain_identity" "main" {
  domain = var.domain
}

# SES Domain DKIM - Email authentication
resource "aws_ses_domain_dkim" "main" {
  domain = aws_ses_domain_identity.main.domain
}

# Route53 Records for Domain Verification
resource "aws_route53_record" "ses_verification" {
  count   = var.create_route53_records ? 1 : 0
  zone_id = var.route53_zone_id
  name    = "_amazonses.${aws_ses_domain_identity.main.domain}"
  type    = "TXT"
  ttl     = 600
  records = [aws_ses_domain_identity.main.verification_token]
}

# Route53 Records for DKIM (email authentication)
resource "aws_route53_record" "ses_dkim" {
  count   = var.create_route53_records ? 3 : 0
  zone_id = var.route53_zone_id
  name    = "${element(aws_ses_domain_dkim.main.dkim_tokens, count.index)}._domainkey.${aws_ses_domain_identity.main.domain}"
  type    = "CNAME"
  ttl     = 600
  records = ["${element(aws_ses_domain_dkim.main.dkim_tokens, count.index)}.dkim.amazonses.com"]
}

# SES Configuration Set for tracking
resource "aws_ses_configuration_set" "main" {
  name = var.configuration_set_name

  delivery_options {
    tls_policy = var.tls_policy
  }

  reputation_metrics_enabled = var.enable_reputation_metrics
  sending_enabled           = var.sending_enabled
}

# CloudWatch for SES metrics
resource "aws_ses_event_destination" "cloudwatch" {
  count                  = var.enable_cloudwatch_events ? 1 : 0
  name                   = "cloudwatch-destination"
  configuration_set_name = aws_ses_configuration_set.main.name
  enabled                = true
  matching_types         = var.cloudwatch_event_types

  cloudwatch_destination {
    default_value  = "default"
    dimension_name = "ses:configuration-set"
    value_source   = "messageTag"
  }
}

# SNS for bounce/complaint notifications
resource "aws_ses_event_destination" "sns" {
  count                  = var.enable_sns_events ? 1 : 0
  name                   = "sns-destination"
  configuration_set_name = aws_ses_configuration_set.main.name
  enabled                = true
  matching_types         = var.sns_event_types

  sns_destination {
    topic_arn = var.sns_topic_arn
  }
}

# Email templates
resource "aws_ses_template" "templates" {
  for_each = var.email_templates

  name    = each.key
  subject = each.value.subject
  html    = each.value.html
  text    = each.value.text
}

# Verified email addresses (for testing or specific senders)
resource "aws_ses_email_identity" "emails" {
  for_each = toset(var.verified_emails)
  email    = each.value
}

# Receipt rule set (optional - for receiving emails)
resource "aws_ses_receipt_rule_set" "main" {
  count          = var.enable_email_receiving ? 1 : 0
  rule_set_name  = var.receipt_rule_set_name
}

resource "aws_ses_active_receipt_rule_set" "main" {
  count          = var.enable_email_receiving ? 1 : 0
  rule_set_name  = aws_ses_receipt_rule_set.main[0].rule_set_name
}

########################################
# SES MODULE - modules/ses/outputs.tf
########################################

output "domain_identity_arn" {
  description = "ARN of the SES domain identity"
  value       = aws_ses_domain_identity.main.arn
}

