########################################
# SES IAM SUBMODULE - modules/ses/iam/variables.tf
########################################

variable "name_prefix" {
  description = "Prefix for IAM policy name"
  type        = string
}

variable "ses_identity_arns" {
  description = "List of SES identity ARNs to allow sending from"
  type        = list(string)
}

variable "iam_role_names" {
  description = "List of IAM role names to attach the SES policy to"
  type        = list(string)
  default     = []
}

variable "restrict_from_addresses" {
  description = "Whether to restrict sending to specific from addresses"
  type        = bool
  default     = false
}

variable "allowed_from_addresses" {
  description = "List of allowed from email addresses (if restrict_from_addresses is true)"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Tags to apply to IAM resources"
  type        = map(string)
  default     = {}
}

########################################
# SES IAM SUBMODULE - modules/ses/iam/main.tf
########################################

# IAM Policy Document for sending emails
data "aws_iam_policy_document" "ses_send_email" {
  statement {
    effect = "Allow"
    actions = [
      "ses:SendEmail",
      "ses:SendRawEmail",
      "ses:SendTemplatedEmail",
      "ses:SendBulkTemplatedEmail"
    ]
    resources = var.ses_identity_arns

    dynamic "condition" {
      for_each = var.restrict_from_addresses ? [1] : []
      content {
        test     = "StringEquals"
        variable = "ses:FromAddress"
        values   = var.allowed_from_addresses
      }
    }
  }
}

# IAM Policy for SES sending
resource "aws_iam_policy" "ses_send_email" {
  name        = "${var.name_prefix}-ses-send-policy"
  description = "Policy to allow sending emails via SES"
  policy      = data.aws_iam_policy_document.ses_send_email.json

  tags = var.tags
}

# Attach policy to roles
resource "aws_iam_role_policy_attachment" "ses_send_email" {
  for_each   = toset(var.iam_role_names)
  role       = each.value
  policy_arn = aws_iam_policy.ses_send_email.arn
}

########################################
# SES IAM SUBMODULE - modules/ses/iam/outputs.tf
########################################

output "policy_arn" {
  description = "ARN of the SES send email policy"
  value       = aws_iam_policy.ses_send_email.arn
}

output "policy_name" {
  description = "Name of the SES send email policy"
  value       = aws_iam_policy.ses_send_email.name
}

variable "topics" {
  type    = list(string)
  default = []
}

resource "aws_sns_topic" "this" {
  for_each = toset(var.topics)
  name     = each.value
}

output "sns_topic_arns" {
  value = [for t in aws_sns_topic.this : t.arn]
}

variable "repositories" {
  description = "List of ECR repository names to create"
  type        = list(string)
}

variable "lifecycle_policies" {
  description = "Map of repository name to lifecycle policy JSON string"
  type        = map(string)
  default     = {}
}

variable "repository_policies" {
  description = "Map of repository name to repository policy JSON string"
  type        = map(string)
  default     = {}
}

variable "region" {
  type        = string
  description = "AWS region for the ECR registry"
}

# Create ECR repositories
resource "aws_ecr_repository" "this" {
  for_each = toset(var.repositories)
  name     = each.value

  image_scanning_configuration {
    scan_on_push = true
  }
}

# Apply lifecycle policies
resource "aws_ecr_lifecycle_policy" "this" {
  for_each   = { for k, v in var.lifecycle_policies : k => v }
  repository = aws_ecr_repository.this[each.key].name
  policy     = each.value
}

# Apply repository policies
resource "aws_ecr_repository_policy" "this" {
  for_each   = { for k, v in var.repository_policies : k => v }
  repository = aws_ecr_repository.this[each.key].name
  policy     = each.value
}

output "repository_arns" {
  value = { for k, v in aws_ecr_repository.this : k => v.arn }
}

output "repository_urls" {
  value = { for k, v in aws_ecr_repository.this : k => v.repository_url }
}

data "aws_caller_identity" "current" {}

output "registry" {
  value       = "${data.aws_caller_identity.current.account_id}.dkr.ecr.${var.region}.amazonaws.com"
  description = "ECR registry URL"
}

variable "image_tag" {
  type        = string
  description = "ECR image tag for production containers."
  default     = "latest"
}


variable "aws_region" {
  description = "AWS region for StitchSense infra"
  type        = string
  default     = "ap-southeast-1"
}

