########################################

output "s3_events_queue_url" {
  value       = aws_sqs_queue.s3_events.url
  description = "S3 events SQS queue URL"
}

output "s3_events_queue_arn" {
  value       = aws_sqs_queue.s3_events.arn
  description = "S3 events SQS queue ARN"
}


