def _common_prefix(dirs: list[list[str]]) -> list[str]:
    if not dirs:
        return []
    lo, hi = min(dirs), max(dirs)  # lexicographic min/max bound every other list
    n = 0
    for a, b in zip(lo, hi):
        if a != b:
            break
        n += 1
    return lo[:n]

