def extract_calls(
    file_path: str,
    content: str,
    known_names: set[str],
) -> list[CallEdge]:
    """
    Parse *content* and return call edges whose callee is in *known_names*.

    known_names — set of all function/method names across the entire repo
                  (used to filter out stdlib / third-party calls).
    """
    ext = Path(file_path).suffix.lower()
    try:
        if ext == ".py":
            return _extract_python_calls(content, known_names)
        if ext in (".ts", ".tsx", ".js", ".jsx"):
            return _extract_js_ts_calls(content, known_names)
        if ext in (".go", ".rs", ".java"):
            return _extract_generic_calls(content, known_names)
    except Exception:
        logger.debug("Call extraction failed | file=%s", file_path, exc_info=True)
    return []

def _extract_python_calls(content: str, known_names: set[str]) -> list[CallEdge]:
    try:
        tree = ast.parse(content)
    except SyntaxError:
        return []

    edges: list[CallEdge] = []
    _walk_py_scope(tree, caller_qname=None, edges=edges, known_names=known_names)
    return edges

def _py_call_name(node: ast.Call) -> str | None:
    """Extract the simple name being called, ignoring attribute chains."""
    func = node.func
    if isinstance(func, ast.Name):
        return func.id
    if isinstance(func, ast.Attribute):
        return func.attr  # e.g. self.foo() → "foo"
    return None

def _extract_js_ts_calls(content: str, known_names: set[str]) -> list[CallEdge]:
    stripped = _strip_comments(content)
    edges: list[CallEdge] = []

    # Collect all function definition ranges with their names
    func_ranges: list[tuple[str, int]] = []  # (qname, start_pos)
    for m in _TS_FUNC_DEF.finditer(stripped):
        name = m.group("n") or m.group("n2")
        if name:
            func_ranges.append((name, m.start()))

    # For each call site, attribute it to the nearest enclosing function
    # (simple heuristic: the last function def that starts before the call)
    for m in _TS_CALL.finditer(stripped):
        callee = m.group("n")
        if callee in _KEYWORDS or callee not in known_names:
            continue
        call_pos = m.start()
        line = _line_of(stripped, call_pos)

        # Find the enclosing function (last def before this call)
        caller: str | None = None
        for fname, fstart in reversed(func_ranges):
            if fstart < call_pos:
                caller = fname
                break

        if caller and caller != callee:
            edges.append((caller, callee, line))

    return edges

def _extract_generic_calls(content: str, known_names: set[str]) -> list[CallEdge]:
    """Detect function calls for Go / Rust / Java.

    Reuses the JS/TS call-site regex plus language-specific function-definition
    regexes to attribute each call to its nearest enclosing function. Unresolved
    (stdlib / third-party) calls are filtered via *known_names*.
    """
    stripped = _strip_generic_comments(content)
    func_defs: list[tuple[str, int]] = []
    for pat in (_GO_FUNC_DEF, _RUST_FUNC_DEF):
        for m in pat.finditer(stripped):
            func_defs.append((m.group(1), m.start()))
    for m in _JAVA_FUNC_DEF.finditer(stripped):
        ret, name = m.group(1), m.group(2)
        if name in _JAVA_CTRL or ret in _JAVA_CTRL:
            continue
        func_defs.append((name, m.start()))
    func_defs.sort(key=lambda x: x[1])

    edges: list[CallEdge] = []
    for m in _TS_CALL.finditer(stripped):
        callee = m.group("n")
        if callee in _GENERIC_KEYWORDS or callee not in known_names:
            continue
        call_pos = m.start()
        caller: str | None = None
        for fname, fstart in reversed(func_defs):
            if fstart < call_pos:
                caller = fname
                break
        if caller and caller != callee:
            edges.append((caller, callee, _line_of(stripped, call_pos)))

    return edges

def _resolve_rust_mod(source_file: str, raw: str, all_paths: List[str]) -> str | None:
    """`mod foo;` in a file declares `foo.rs` (or `foo/mod.rs`) next to it."""
    source_dir = str(Path(source_file).parent).replace("\\", "/")
    base = f"{source_dir}/{raw}"
    for candidate in (base + ".rs", base + "/mod.rs"):
        n = _normalize(candidate).lstrip("./")
        for p in all_paths:
            if _normalize(p) == n:
                return p
    return None

def _resolve_rust_use(raw: str, all_paths: List[str]) -> str | None:
    """`use crate::a::b;` -> module `a` (last segment is the item name)."""
    parts = [p for p in raw.split("/") if p not in ("crate", "self", "super")]
    if not parts:
        return None
    module = "/".join(parts[:-1]) if len(parts) > 1 else parts[0]
    for candidate in (module + ".rs", module + "/mod.rs"):
        n = _normalize(candidate).lstrip("./")
        for p in all_paths:
            if _normalize(p).endswith(n):
                return p
    return None

def _resolve_java_import(raw: str, all_paths: List[str]) -> str | None:
    """Java import `com/foo/Bar` -> `com/foo/Bar.java` if it exists in repo.

    Falls back to matching by file basename when the package directory layout
    isn't mirrored on disk.
    """
    n = _normalize(raw + ".java").lstrip("./")
    for p in all_paths:
        if _normalize(p).endswith(n):
            return p
    base = raw.split("/")[-1] + ".java"
    for p in all_paths:
        if p.split("/")[-1] == base:
            return p
    return None

