def _dedupe_symbols(symbols: list[dict[str, Any]]) -> list[dict[str, Any]]:
    seen: set[tuple] = set()
    out = []
    for s in symbols:
        key = (s["name"], s["line_start"], s["symbol_type"])
        if key not in seen:
            seen.add(key)
            out.append(s)
    return out

