                    "risks": [], "steps": []}
        data["id"] = flow.get("id")
        enriched.append(data)
    return {"flows": enriched}

def _learn_mod_of(path: Optional[str]) -> Optional[str]:
    if not path:
        return None
    return path.split("/")[0] if "/" in path else "__root__"

def learn_build_flow_graph_node(state: LearnState):
    """Build a zoomable graph per flow from deterministic data + enriched steps."""
    symbols = state.get("symbols", [])
    func_edges = state.get("func_edges", [])
    sig_by_file_name: dict = {}
    for s in symbols:
        sig_by_file_name.setdefault(s["file_path"], {})[s["name"]] = s

    graphs = []
    for fl in state.get("flows", []):
        nodes: dict = {}
        edges: list = []

        fid = fl.get("id") or f"flow-{len(graphs) + 1}"
        nodes[fid] = {
            "id": fid, "kind": "feature", "label": fl.get("name", "Unnamed flow"),
            "parent": None,
            "detail": {"summary": fl.get("description", ""), "source_file": None,
                       "code_ref": None, "line": None},
        }

        comps: set = set()
        func_nodes: dict = {}
        for st in fl.get("steps", []):
            fpath = st.get("file")
            fname = st.get("name")
            mod = _learn_mod_of(fpath)
            if mod:
                comps.add(mod)
            if fpath and fname:
                nid = f"{fpath}::{fname}"
                if nid not in func_nodes:
                    detail = sig_by_file_name.get(fpath, {}).get(fname, {})
                    func_nodes[nid] = {
                        "id": nid,
                        "kind": st.get("type") or "function",
                        "label": fname,
                        "parent": mod,
                        "detail": {
                            "summary": st.get("insight") or st.get("description", ""),
                            "source_file": fpath,
                            "code_ref": _learn_symbol_signature(detail) if detail else fname,
                            "line": detail.get("line_start") if detail else None,
                        },
                    }

        for m in comps:
            nid = f"mod::{m}"
            nodes[nid] = {"id": nid, "kind": "component", "label": m, "parent": fid,
                          "detail": {"summary": "", "source_file": None,
                                     "code_ref": None, "line": None}}
            edges.append({"from": fid, "to": nid, "kind": "contains", "label": ""})

        for nid, n in func_nodes.items():
            nodes[nid] = n
            if n["parent"]:
                edges.append({"from": f"mod::{n['parent']}", "to": nid,
                              "kind": "contains", "label": ""})

        known_func_ids = set(func_nodes)
        for e in func_edges:
            cs = f"{e['file']}::{e['source']}"
            ct = f"{e['file']}::{e['target']}"
            if cs in known_func_ids and ct in known_func_ids:
                edges.append({"from": cs, "to": ct, "kind": "call", "label": ""})

        graphs.append({
            "id": fid,
            "name": fl.get("name", "Unnamed flow"),
            "description": fl.get("description", ""),
            "risks": fl.get("risks", []),
            "graph": {"nodes": list(nodes.values()), "edges": edges},
        })
    return {"flow_graph": {"flows": graphs}}

def _learn_find_handler_name(content: Optional[str], method: str, path: str) -> Optional[str]:
    """Best-effort: return the handler function name for a route decorator."""
    if not content:
        return None
    target = _learn_norm_path(path)
    m_upper = method.upper()
    for m in _PY_DECORATOR_ROUTE.finditer(content):
        mm = m.group("m").upper()
        if mm == "ROUTE":
            mm = "GET"
        if mm != m_upper:
            continue
        if _learn_norm_path(m.group("p")) == target:
            tail = content[m.end():]
            fm = re.search(r"(?:async\s+def|def)\s+([A-Za-z_]\w*)\s*\(", tail)
            if fm:
                return fm.group(1)
    return None

def _learn_handler_symbol(state: LearnState, route: dict):
    """Resolve the handler symbol (with source_code + params) for a route, or None."""
    name = _learn_find_handler_name(
        state.get("file_map", {}).get(route["file"], {}).get("content"),
        route["method"], route["path"],
    )
    if not name:
        return None
    for s in state.get("symbols", []):
        if s.get("file_path") == route["file"] and s.get("name") == name:
            return s
    return None

def _learn_looks_like_model(typ: str) -> bool:
    """Heuristic: does this annotation refer to a request/response model (body)?"""
    if not typ:
        return False
    t = typ.strip()
    for wrapper in ("Optional", "Annotated", "Union", "List", "Sequence",
                    "Tuple", "Dict", "Set"):
        pref = f"{wrapper}["
        if t.startswith(pref):
            inner = t[len(pref):-1]
            parts = [p.strip() for p in inner.split(",")]
            return any(_learn_looks_like_model(p) for p in parts)
    base = re.split(r"[\[\], \.]", t)[0].strip()
    if not base or base in _LEARN_PRIMITIVES:
        return False
    return base[:1].isupper()

def _learn_params_from_symbol(symbol: dict, path: str) -> list:
    """Deterministic extraction of endpoint params from a handler signature."""
    try:
        raw = json.loads(symbol.get("parameters") or "[]")
    except Exception:
        return []
    if not isinstance(raw, list):
        return []
    path_params = set(re.findall(r"\{(\w+)\}", path or ""))
    out = []
    for p in raw:
        if not isinstance(p, dict):
            continue
        name = p.get("name", "")
        if not name or name.startswith("*"):
            continue
        typ = p.get("type") or ""
        if name in path_params:
            pin, req = "path", True
        elif _learn_looks_like_model(typ):
            pin, req = "body", True
        else:
            pin, req = "query", (p.get("default") is None)
        out.append({
            "name": name, "in": pin, "type": typ,
            "required": bool(req), "description": "",
        })
    return out

def _learn_api_batch_context(state: LearnState, mod: str, routes: list) -> str:
    lines = [f"MODULE: {mod}", f"ROUTES ({len(routes)}):"]
    for r in routes:
        lines.append(f"  {r['method']} {r['path']}  ({r['file']})")
    lines.append("")
    lines.append("HANDLER SIGNATURES + SOURCE (use these to derive params, body, "
                 "response, errors and examples):")
    for r in routes:
        sym = _learn_handler_symbol(state, r)
        if not sym:
            continue
        lines.append(f"\n  # {r['method']} {r['path']} -> {sym['name']}")
        lines.append(f"  {_learn_symbol_signature(sym)}")
        src = sym.get("source_code")
        if src:
            indented = "\n".join("    " + ln for ln in src.splitlines())
            lines.append(f"  source:")
            lines.append(indented)
    return "\n".join(lines)

async def learn_api_explore_node(state: LearnState):
    groups = state.get("api_groups", {})
    if not groups:
        return {"apis": []}

    enriched = []
    for mod, routes in list(groups.items())[:LEARN_MAX_API_GROUPS]:
        endpoints: list = []
        for i in range(0, len(routes), LEARN_API_BATCH):
            endpoints += await _learn_api_batch(
                state, mod, routes[i:i + LEARN_API_BATCH]
            )
        if endpoints:
            enriched.append({"group": mod, "endpoints": endpoints})
    return {"apis": enriched}

def _learn_norm_feature(name: str) -> str:
    """Normalise a feature/use-case group name for cross-chunk de-duplication."""
    name = _learn_str(name).strip()
    name = re.sub(r"\s+", " ", name)
    return name.lower()

def _learn_chunks(seq: list, n: int):
    for i in range(0, len(seq), n):
        yield seq[i:i + n]

async def learn_group_apis_node(state: LearnState):
    """Re-group enriched endpoints by feature/use-case (LLM-driven).

    ``api_explore`` groups endpoints by module. This step asks the LLM to cluster
    them into feature/use-case groups so the UI can present a clickable feature
    list instead of one flat module list. Falls back to the existing module
    grouping if the LLM step yields nothing usable.
    """
    apis_in = state.get("apis") or []
    flat = []
    for grp in apis_in:
        for ep in _learn_list(grp.get("endpoints")):
            if isinstance(ep, dict) and ep.get("method") and ep.get("path"):
                flat.append(ep)
    if not flat:
        return {"apis": []}

    by_key = {(e.get("method"), e.get("path")): e for e in flat}
    merged: dict = {}
    seen: set = set()
    for chunk in _learn_chunks(flat, LEARN_API_GROUP_CHUNK):
        for g in await _learn_feature_group_batch(state, chunk):
            name = _learn_norm_feature(g["group"])
            if not name:
                continue
            bucket = merged.setdefault(name, {"group": g["group"], "endpoints": []})
            for ref in g["endpoints"]:
                key = (ref.get("method"), ref.get("path"))
                if key in seen:
                    continue
                doc = by_key.get(key)
                if doc:
                    bucket["endpoints"].append(doc)
                    seen.add(key)

    if not merged:
        # LLM grouping produced nothing usable: keep module grouping.
        return {"apis": apis_in}

    missing = [by_key[k] for k in by_key if k not in seen]
    if missing:
        other = merged.setdefault("other", {"group": "Other", "endpoints": []})
        other["endpoints"].extend(missing)

    result = sorted(merged.values(), key=lambda b: -len(b["endpoints"]))
    if len(result) > LEARN_MAX_API_GROUPS:
        overflow = result[LEARN_MAX_API_GROUPS:]
        result = result[:LEARN_MAX_API_GROUPS]
        other = result[-1]
        other["group"] = "Other"
        for b in overflow:
            other["endpoints"].extend(b["endpoints"])
    return {"apis": result}

def learn_codebase_node(state: LearnState):
    files = state.get("file_map", {})
    modules = state.get("modules", [])
    symbols = state.get("symbols", [])
    file_deps = state.get("file_deps", [])

    module_files: dict = {}
    for path in files:
        parts = path.split("/")
        mod = parts[0] if len(parts) > 1 else "__root__"
        module_files.setdefault(mod, []).append(path)

    symbols_by_file: dict = {}
    for s in symbols:
        symbols_by_file.setdefault(s["file_path"], []).append(s)

    out_modules = []
    for m in modules:
        mod = m["module"]
        file_entries = []
        for fpath in sorted(module_files.get(mod, [])):
            syms = [
                {"name": s["name"], "kind": s.get("symbol_type", "function"),
                 "signature": _learn_symbol_signature(s),
                 "line": s.get("line_start")}
                for s in symbols_by_file.get(fpath, [])
            ]
            file_entries.append({
                "path": fpath,
                "symbol_count": len(syms),
                "symbols": syms[:60],
            })
        out_modules.append({
            "module": mod,
            "file_count": m["file_count"],
            "depends_on": m["depends_on"],
            "files": file_entries[:80],
        })

    dependencies = [
        {"from": e["source"], "to": e["target"], "kind": e.get("import_type", "import")}
        for e in file_deps[:400]
    ]

    return {
        "codebase": {
            "modules": out_modules,
            "dependencies": dependencies,
            "symbols_total": len(symbols),
            "routes_total": len(state.get("routes", [])),
        }
    }

def _learn_api_param(p):
    if not isinstance(p, dict):
        return {"name": _learn_str(p), "in": "query", "type": "", "required": False, "description": ""}
    return {
        "name": _learn_str(p.get("name")),
        "in": _learn_str(p.get("in")) or "query",
        "type": _learn_str(p.get("type")),
        "required": bool(p.get("required", False)),
        "description": _learn_str(p.get("description")),
    }

def learn_normalize(state: LearnState) -> dict:
    overview_in = state.get("overview", {}) if isinstance(state.get("overview"), dict) else {}
    flows_in = state.get("flows", [])
    flow_graph = state.get("flow_graph", {}).get("flows", []) if isinstance(state.get("flow_graph"), dict) else []
    apis_in = state.get("apis", [])
    codebase_in = state.get("codebase", {}) if isinstance(state.get("codebase"), dict) else {}

    # --- area 1: overview ---
    ov_modules = []
    for m in _learn_list(overview_in.get("modules")):
        if isinstance(m, dict) and _learn_str(m.get("name")):
            ov_modules.append({
                "name": _learn_str(m.get("name")),
                "responsibility": _learn_str(m.get("responsibility")),
                "connects_to": [_learn_str(c) for c in _learn_list(m.get("connects_to")) if _learn_str(c)],
                "key_files": [_learn_str(f) for f in _learn_list(m.get("key_files")) if _learn_str(f)],
            })
    connections = []
    for c in _learn_list(overview_in.get("connections")):
        if isinstance(c, dict) and _learn_str(c.get("from")) and _learn_str(c.get("to")):
            connections.append({
                "from": _learn_str(c.get("from")),
                "to": _learn_str(c.get("to")),
                "note": _learn_str(c.get("note")),
            })
    business_logic = []
    for b in _learn_list(overview_in.get("business_logic")):
        if isinstance(b, dict) and _learn_str(b.get("topic")):
            business_logic.append({
                "topic": _learn_str(b.get("topic")),
                "locations": [_learn_str(loc) for loc in _learn_list(b.get("locations")) if _learn_str(loc)],
            })
    overview = {
        "summary": _learn_str(overview_in.get("summary")),
        "modules": ov_modules,
        "entry_points": [_learn_str(x) for x in _learn_list(overview_in.get("entry_points")) if _learn_str(x)],
        "connections": connections,
        "framework": _learn_list(state.get("framework")),
    }

    # --- area 2: flows (graph + narrative) ---
    flow_out = []
    flow_by_id = {f.get("id"): f for f in flow_graph}
    for fl in _learn_list(flows_in):
        if not isinstance(fl, dict):
            continue
        fid = fl.get("id")
        g = flow_by_id.get(fid, {}).get("graph", {"nodes": [], "edges": []})
        steps = []
        for s in _learn_list(fl.get("steps")):
            if not isinstance(s, dict):
                continue
            name = _learn_str(s.get("name"))
            if not name:
                continue
            steps.append({
                "name": name,
                "description": _learn_str(s.get("description")),
                "type": _learn_str(s.get("type")) or "function",
                "file": _learn_str(s.get("file")) or None,
                "line": s.get("line"),
                "insight": _learn_str(s.get("insight")) or None,
            })
        flow_out.append({
            "id": _learn_str(fid) or f"flow-{len(flow_out) + 1}",
            "name": _learn_str(fl.get("name")) or "Unnamed flow",
            "description": _learn_str(fl.get("description")),
            "risks": [_learn_str(r) for r in _learn_list(fl.get("risks")) if _learn_str(r)],
            "graph": {"nodes": g.get("nodes", []), "edges": g.get("edges", [])},
            "steps": steps,
        })

    # --- area 3: apis (grouped) ---
    apis_out = []
    for grp in _learn_list(apis_in):
        if not isinstance(grp, dict):
            continue
        endpoints = []
        for e in _learn_list(grp.get("endpoints")):
            if not isinstance(e, dict):
                continue
            endpoints.append({
                "method": _learn_str(e.get("method")),
                "path": _learn_str(e.get("path")),
                "summary": _learn_str(e.get("summary")),
                "behavior": _learn_str(e.get("behavior")),
                "params": [_learn_api_param(p) for p in _learn_list(e.get("params"))],
                "headers": [_learn_str(h) for h in _learn_list(e.get("headers")) if _learn_str(h)],
                "body_schema": _learn_str(e.get("body_schema")),
                "response": _learn_str(e.get("response")),
                "errors": [_learn_str(x) for x in _learn_list(e.get("errors")) if _learn_str(x)],
                "example": _learn_str(e.get("example")),
                "source_files": [_learn_str(f) for f in _learn_list(e.get("source_files")) if _learn_str(f)],
                "related": [_learn_str(r) for r in _learn_list(e.get("related")) if _learn_str(r)],
            })
        if not endpoints:
            continue
        apis_out.append({"group": _learn_str(grp.get("group")) or "api", "endpoints": endpoints})

    # --- area 4: codebase ---
    cb_modules = []
    resp_by_name = {m["name"]: m.get("responsibility", "") for m in ov_modules}
    for m in _learn_list(codebase_in.get("modules")):
        if not isinstance(m, dict):
            continue
        files = []
        for f in _learn_list(m.get("files")):
            if not isinstance(f, dict):
                continue
            files.append({
                "path": _learn_str(f.get("path")),
                "symbol_count": f.get("symbol_count", 0),
                "symbols": _learn_list(f.get("symbols")),
            })
        cb_modules.append({
            "module": _learn_str(m.get("module")),
            "responsibility": resp_by_name.get(_learn_str(m.get("module")), ""),
            "file_count": m.get("file_count", 0),
            "depends_on": _learn_list(m.get("depends_on")),
            "files": files,
        })
    codebase = {
        "modules": cb_modules,
        "dependencies": _learn_list(codebase_in.get("dependencies")),
        "symbols_total": codebase_in.get("symbols_total", 0),
        "routes_total": codebase_in.get("routes_total", 0),
        "business_logic": business_logic,
    }

    warnings = [_learn_str(w) for w in _learn_list(overview_in.get("warnings")) if _learn_str(w)]
    if not ov_modules and not flow_out and not apis_out and not cb_modules:
        warnings.append("No usable learn information was produced.")

    return {
        "schema_version": 2,
        "overview": overview,
        "flows": flow_out,
        "apis": apis_out,
        "codebase": codebase,
        "warnings": warnings,
    }

def setup_collect_from_db(rows):
    """Build the same (tree, lockfiles, files) tuple as setup_collect, but from
    stored RepositoryFile rows instead of a disk folder. Each ``row`` exposes
    ``path`` and ``content`` (and optionally ``size_bytes``).
    """
    tree, lockfiles, files = {}, [], {}
    for row in rows:
        path = row.path
        low = path.split("/")[-1].lower()
        size = getattr(row, "size_bytes", None) or 0
        if low in SETUP_LOCKFILES:
            lockfiles.append(path)
        elif setup_kind(path, low) and row.content is not None and size < 200_000:
            files[path] = row.content

    # Shallow folder tree (top two levels), mirroring setup_collect's shape so
    # the LLM sees the same structure.
    for path in files:
        low = path.split("/")[-1].lower()
        parts = path.split("/")
        if len(parts) <= 2:
            folder = "/".join(parts[:-1]) or "."
            name_ok = (not low.startswith("readme")) and (
                not low.startswith(".env") or setup_kind(path, low) == "env"
            )
            if name_ok and low not in tree.setdefault(folder, []):
                tree[folder].append(low)
    for folder in tree:
        tree[folder] = sorted(tree[folder])[:15]
    return tree, lockfiles, files

def setup_clean(p):
    """Remove a leading './' from a path (lstrip would also eat the dot of '.env')."""
    return p[2:] if p.startswith("./") else p

def setup_collect(root, max_depth=3):
    """Return (tree, lockfiles, files) for the project at `root`."""
    root = Path(root)
    tree, lockfiles, files = {}, [], {}
    for dirpath, dirs, names in os.walk(root):
        dirs[:] = [d for d in dirs if d not in SETUP_SKIP_DIRS]
        rel = Path(dirpath).relative_to(root)
        if len(rel.parts) > max_depth:
            dirs[:] = []
            continue
        if len(rel.parts) <= 2:
            tree[rel.as_posix()] = [n for n in sorted(names)
                                    if not n.lower().startswith("readme")
                                    and not n.lower().startswith(".env")
                                    or setup_kind(n, n.lower()) == "env"][:15]
        for name in names:
            path = (rel / name).as_posix()
            low = name.lower()
            full = Path(dirpath) / name
            if low in SETUP_LOCKFILES:
                lockfiles.append(path)
            elif setup_kind(path, low) and full.stat().st_size < 200_000:
                files[path] = full.read_text(errors="ignore")
    return tree, lockfiles, files

def setup_compress_package_json(text):
    try:
        pkg = json.loads(text)
    except ValueError:
        return text[:3000]
    keep = {k: pkg[k] for k in ("name", "scripts", "engines", "packageManager", "workspaces") if k in pkg}
    keep["dependencies"] = list(pkg.get("dependencies", {}))[:15]
    return json.dumps(keep, indent=1)

def setup_compress(tree, lockfiles, files):
    by_kind = {}
    for path, text in files.items():
        by_kind.setdefault(setup_kind(path, setup_name(path)), []).append((path, text))

    small, used, left_out = {}, 0, []
    for kind in SETUP_PRIORITY:
        # Shallow paths first: in a monorepo the root files matter most.
        items = sorted(by_kind.get(kind, []), key=lambda it: (it[0].count("/"), it[0]))
        for i, (path, text) in enumerate(items):
            body = setup_compress_package_json(text) if path.endswith("package.json") \
                else text[:SETUP_LIMITS[kind]]
            if i >= SETUP_MAX_PER_KIND[kind] or used + len(body) > SETUP_TOTAL_CHARS:
                left_out.append(path)                            # no room: just list the name
                continue
            small[path] = body
            used += len(body)
    return {"folders": tree, "lockfiles": lockfiles, "files": small, "not_included": left_out[:40]}

def setup_str(x):
    """Any value -> a clean string ('' for None)."""
    return "" if x is None else str(x).strip()

def setup_list(x):
    """Anything that isn't a list becomes an empty list."""
    return x if isinstance(x, list) else []

def setup_normalize(guide):
    """Turn whatever the LLM returned into the fixed shape above. Never raises."""
    guide = guide if isinstance(guide, dict) else {}

    env_vars = []
    for v in setup_list(guide.get("env_vars")):
        v = {"name": v} if isinstance(v, str) else v            # accept ["API_KEY", ...]
        if isinstance(v, dict) and setup_str(v.get("name")):
            env_vars.append({"name": setup_str(v["name"]), "purpose": setup_str(v.get("purpose"))})

    services = []
    for sv in setup_list(guide.get("services")):
        name = setup_str(sv.get("name")) if isinstance(sv, dict) else setup_str(sv)   # accept objects too
        if name:
            services.append(name)

    files_guide = []
    for f in setup_list(guide.get("files_guide")):
        if isinstance(f, dict) and setup_str(f.get("file")):
            files_guide.append({"file": setup_str(f["file"]), "purpose": setup_str(f.get("purpose"))})

    run_options = []
    for opt in setup_list(guide.get("run_options")):
        if not isinstance(opt, dict):
            continue
        steps = []
        for st in setup_list(opt.get("steps")):
            if not isinstance(st, dict):
                continue
            title, cmd = setup_str(st.get("title")), setup_str(st.get("command"))
            if not title and not cmd:
                continue                                         # empty step: drop it
            phase = setup_str(st.get("phase")).lower()
            steps.append({
                "title": title or cmd,
                "description": setup_str(st.get("description")),
                "command": cmd,
                "phase": phase if phase in SETUP_PHASES else "run",
                "source_file": setup_str(st.get("source_file")),
            })
        if not steps:
            continue                                             # option with no steps: drop it
        rel = setup_str(opt.get("reliability")).lower()
        run_options.append({
            "name": setup_str(opt.get("name")) or f"Option {len(run_options) + 1}",
            "reliability": rel if rel in SETUP_RELIABILITY else "medium",
            "best_for": setup_str(opt.get("best_for")),
            "requires": [setup_str(r) for r in setup_list(opt.get("requires")) if setup_str(r)],
            "steps": steps,
        })

    warnings = [] if run_options else ["No usable run options were produced."]
    return {"schema_version": SETUP_SCHEMA_VERSION, "summary": setup_str(guide.get("summary")),
            "env_vars": env_vars, "services": services, "files_guide": files_guide,
            "run_options": run_options, "warnings": warnings}

def as_node(name, builder):
    """Wrap a subgraph as one parent node. Only its output and errors come back."""
    subgraph = builder()

    async def run(state):
        try:
            result = await subgraph.ainvoke({
                "project_root": state["project_root"],
                "files": state.get("files"),
            })
            return {"sections": {name: result.get("output", {})},
                    "errors": result.get("errors", [])}
        except Exception as e:
            return {"sections": {name: {}}, "errors": [f"{name}: {e}"]}

    return run

def setup_compose_ok(part, paths, all_text):
    """Check a `docker compose ...` command: -f files exist, service names exist."""
    tokens = part.split()
    used = [tokens[i + 1] for i, t in enumerate(tokens[:-1]) if t in ("-f", "--file")]
    for f in used:                                          # every -f file must exist
        if setup_clean(f) not in paths:
            return False
    if not used and not any(setup_kind(p, setup_name(p)) == "compose" for p in paths):
        return False                                        # no compose file at all
    if "up" in tokens or "build" in tokens:                 # service names must exist
        start = tokens.index("up") if "up" in tokens else tokens.index("build")
        skip_next = False
        for t in tokens[start + 1:]:
            if skip_next:
                skip_next = False
            elif t in ("--profile", "--scale", "-p"):
                skip_next = True
            elif not t.startswith("-") and f"{t}:" not in all_text:
                return False
    return True

def setup_check(guide, data):
    all_text = "\n".join(data["files"].values())
    paths = set(data["files"])
    warnings = []
    for opt in guide.get("run_options", []):
        for step in opt.get("steps", []):
            cmd = (step.get("command") or "").strip()
            step["verified"] = (not cmd) or all(
                setup_part_is_real(p.strip(), paths, all_text) for p in cmd.split("&&"))
            if not step["verified"]:
                warnings.append(f"[{opt.get('name')}] Unverified command: {cmd}")
    guide["warnings"] = guide.get("warnings", []) + warnings
    return guide

def setup_collect_node(state):
    if state.get("files"):
        tree, lockfiles, files = setup_collect_from_db(state["files"])
    else:
        tree, lockfiles, files = setup_collect(state["project_root"])
    return {"tree": tree, "lockfiles": lockfiles, "files": files}

async def setup_llm_node(state):
    try:
